import Link from "next/link";
import { Mail } from "lucide-react";
import { FooterWordmark } from "@/components/footer-wordmark";
import "./footer.css";

const columns = [
  {
    title: "Product",
    links: [
      ["Templates", "/templates"],
      ["Contacts", "/contacts"],
      ["Send queue", "/history"],
      ["Allowances", "/usage"],
    ],
  },
  {
    title: "Support",
    links: [
      ["Help center", "/help"],
      ["FAQ", "/help#faq"],
      ["Contact us", "/contact"],
    ],
  },
  {
    title: "Legal",
    links: [
      ["Privacy", "/privacy"],
      ["Terms", "/terms"],
    ],
  },
];
const focus =
  "focus-visible:outline-2! focus-visible:outline-solid! focus-visible:outline-[var(--footer-accent)]! focus-visible:outline-offset-[3px]!";
const footerLink = `${focus} footer-link relative inline-block py-[5px] text-[14.5px] text-[var(--footer-muted)] no-underline [--footer-underline-bottom:1px]`;

function FooterNavigation({
  title,
  links,
  className = "",
}: {
  title: string;
  links: string[][];
  className?: string;
}) {
  return (
    <nav
      aria-label={title}
      className={`self-center [@media(max-width:860px)]:self-start ${className}`}
    >
      <h3 className="mb-2.5 text-[14px] font-semibold">{title}</h3>
      <ul className="m-0 grid list-none gap-px p-0">
        {links.map(([label, href]) => (
          <li key={label}>
            <Link
              href={href}
              className={`${footerLink} inline-flex min-h-11 items-center`}
            >
              {label}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}

function CreatorCredit({ landing = false }: { landing?: boolean }) {
  return (
    <a
      href="https://x.com/itsCzar16"
      target="_blank"
      rel="noopener"
      className={`${focus} footer-link relative inline-flex items-center gap-[7px] text-[var(--footer-muted)] no-underline ${landing ? "min-h-11" : ""}`}
    >
      <svg
        aria-hidden="true"
        width="13"
        height="13"
        viewBox="0 0 24 24"
        fill="currentColor"
      >
        <path d="M18.901 1.153h3.68l-8.04 9.19L24 22.846h-7.406l-5.8-7.584-6.64 7.584H.47l8.6-9.835L0 1.154h7.594l5.243 6.932 6.064-6.933Zm-1.29 19.49h2.039L6.487 3.24H4.3l13.31 17.403Z" />
      </svg>
      <span>
        Made by <span translate="no">Czarl6</span>
      </span>
    </a>
  );
}

export function Footer({
  variant = "landing",
}: {
  variant?: "landing" | "pricing" | "workspace";
}) {
  if (variant === "pricing")
    return (
      <footer
        data-site-footer
        data-footer-variant="pricing"
        className="mt-8 pt-6 border-t border-dotted border-separator text-[var(--pricing-muted)] text-[13px] [--footer-text:var(--pricing-text)] [--footer-accent:var(--pricing-accent)]"
      >
        <nav
          aria-label="Footer"
          className="flex flex-wrap justify-center gap-y-3 gap-x-6"
        >
          <Link className="footer-link relative no-underline" href="/">
            Home
          </Link>
          <Link className="footer-link relative no-underline" href="/pricing">
            Pricing
          </Link>
          <Link className="footer-link relative no-underline" href="/privacy">
            Privacy Policy
          </Link>
          <Link className="footer-link relative no-underline" href="/terms">
            Terms of Service
          </Link>
        </nav>
      </footer>
    );
  return (
    <footer
      data-site-footer
      data-footer-variant={variant}
      className="relative isolate w-full overflow-hidden border-t border-dotted border-separator bg-[var(--footer-panel)] text-[var(--footer-text)] [font-family:var(--font-plus-jakarta),sans-serif] leading-[1.55] [--footer-panel:var(--landing-bg,var(--background))] [--footer-surface:var(--surface)] [--footer-text:var(--foreground)] [--footer-muted:var(--muted-foreground)] [--footer-accent:var(--accent)] [--footer-ok:var(--success)]"
    >
      {variant === "workspace" ? (
        <div className="page-container">
          <div className="grid grid-cols-[minmax(0,1fr)_minmax(0,2fr)_minmax(0,1fr)] items-center gap-8 py-6 [@media(max-width:860px)]:grid-cols-2 [@media(max-width:860px)]:gap-x-6 [@media(max-width:860px)]:gap-y-6">
            <nav
              aria-label="Support"
              className="grid justify-items-start gap-px"
            >
              {columns[1].links
                .filter(([label]) => label !== "FAQ")
                .map(([label, href]) => (
                  <Link key={label} href={href} className={footerLink}>
                    {label}
                  </Link>
                ))}
            </nav>
            <Link
              href="/"
              aria-label="Mailloop home"
              className={`${focus} block min-w-0 [@media(max-width:860px)]:order-first [@media(max-width:860px)]:col-span-full`}
            >
              <FooterWordmark
                maxFontSize={112}
                particlePaddingRatio={0.12}
                className="mt-0 max-w-[480px] px-0 pb-3"
              />
            </Link>
            <nav
              aria-label="Legal"
              className="grid justify-items-end gap-px [@media(max-width:860px)]:justify-items-start"
            >
              {columns[2].links.map(([label, href]) => (
                <Link key={label} href={href} className={footerLink}>
                  {label}
                </Link>
              ))}
            </nav>
          </div>
          <div
            data-footer-utility
            className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 py-[18px] text-[13.5px] text-[var(--footer-muted)]"
          >
            <Link
              href="/"
              translate="no"
              className={`${focus} inline-flex items-center gap-2 text-[16px] font-semibold tracking-[-0.02em] text-[var(--footer-text)] no-underline`}
            >
              <span
                aria-hidden="true"
                className="grid size-6 place-items-center rounded-[7px] bg-[var(--footer-btn-bg)] text-[var(--footer-btn-text)]"
              >
                <Mail size={16} strokeWidth={1.8} />
              </span>
              mailloop
            </Link>
            <span>
              © 2026 <span translate="no">mailloop</span>
            </span>
            <CreatorCredit />
          </div>
        </div>
      ) : (
        <div className="mx-auto max-w-[1180px] px-[clamp(24px,5vw,56px)]">
          <div className="grid grid-cols-[minmax(0,1fr)_minmax(0,2fr)_minmax(0,1fr)] items-center gap-x-8 gap-y-3 py-12 [@media(max-width:860px)]:grid-cols-2 [@media(max-width:860px)]:gap-x-6 [@media(max-width:860px)]:py-9">
            <FooterNavigation
              {...columns[0]}
              className="col-start-1 row-start-1 [@media(max-width:860px)]:row-start-3 [@media(max-width:860px)]:mt-6"
            />
            <Link
              href="/"
              aria-label="Mailloop home"
              className={`${focus} col-start-2 row-start-1 block min-w-0 text-center no-underline [@media(max-width:860px)]:col-start-1 [@media(max-width:860px)]:col-span-full`}
            >
              <FooterWordmark
                maxFontSize={180}
                particlePaddingRatio={0.12}
                className="mt-0 px-0 pb-0"
              />
            </Link>
            <p className="col-start-2 row-start-2 text-center text-[14.5px] leading-[1.6] text-[var(--footer-muted)] [@media(max-width:860px)]:col-start-1 [@media(max-width:860px)]:col-span-full">
              Personalized outreach, made easy.
            </p>
            <div className="col-start-3 row-start-1 flex flex-wrap items-center justify-between gap-x-6 gap-y-7 self-center [@media(max-width:860px)]:mt-6 [@media(max-width:860px)]:col-start-2 [@media(max-width:860px)]:row-start-3 [@media(max-width:860px)]:self-start [@media(max-width:860px)]:items-start [@media(max-width:860px)]:flex-col">
              {columns.slice(1).map(({ title, links }) => (
                <FooterNavigation key={title} title={title} links={links} />
              ))}
            </div>
          </div>
          <div
            data-footer-utility
            className="relative z-[1] flex flex-wrap items-center justify-between gap-x-6 gap-y-3 py-[18px] text-[13.5px] text-[var(--footer-muted)]"
          >
            <span>
              © 2026 <span translate="no">mailloop</span>
            </span>
            <CreatorCredit landing />
          </div>
        </div>
      )}
    </footer>
  );
}
